"""Prepare the frozen C32 adapter source used by full-v2 native regression tests."""
from pathlib import Path
import io
import shutil
import subprocess
import tarfile

ROOT = Path(__file__).resolve().parents[1]
source = ROOT / '.deps/dxvk-remix'
frozen = ROOT / '.deps/c32-frozen'
out = ROOT / 'work/c32-source'
out.mkdir(parents=True, exist_ok=True)
archive = subprocess.check_output(['git', 'archive', 'HEAD', 'bridge'], cwd=source)
with tarfile.open(fileobj=io.BytesIO(archive)) as tar:
    tar.extractall(out, filter='data')
subprocess.run(['git', 'init', '-q', str(out)], check=True)
for name in ('l4d2-bridge.patch', 'ipc-c32.patch'):
    patch = frozen / 'patches' / name
    subprocess.run(['git', 'apply', '--check', str(patch)], cwd=out, check=True)
    subprocess.run(['git', 'apply', str(patch)], cwd=out, check=True)
util = out / 'bridge/src/util'
(util / 'ipc_v2').mkdir(exist_ok=True)
for name in ('platform.h', 'transport.h'):
    shutil.copy2(frozen / 'experiments/ipc-v2' / name, util / 'ipc_v2' / name)
shutil.copy2(frozen / 'experiments/ipc-c32/message_queue.h', util / 'ipc_c32_message_queue.h')
print('Frozen C32 fixture prepared; production remains the canonical v1.3.0 patch')
